<!doctype html>
<html lang="da">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Node Setup · Nodexa</title>
<style>
:root{color-scheme:dark;--bg:#080a0f;--panel:#10141d;--panel2:#151a25;--line:#252c3a;--text:#f4f6fb;--muted:#8d97aa;--purple:#765cff;--purple2:#9a72ff;--green:#31d09b;--red:#ff6683}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 18% 0,rgba(111,74,255,.16),transparent 31%),var(--bg);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{min-height:100vh;display:grid;grid-template-columns:250px 1fr}.side{border-right:1px solid var(--line);background:rgba(11,14,20,.94);padding:22px 16px;position:sticky;top:0;height:100vh}.brand{display:flex;gap:12px;align-items:center;padding:3px 8px 26px}.mark{width:38px;height:38px;border-radius:11px;background:linear-gradient(135deg,var(--purple),var(--purple2));display:grid;place-items:center;font-weight:900}.brand b{font-size:18px;letter-spacing:.12em}.brand b span{color:#9c7bff}.brand small{display:block;color:#626d80;font-size:10px;letter-spacing:.15em;margin-top:3px}.navlabel{color:#5f697b;font-size:10px;font-weight:800;letter-spacing:.14em;padding:15px 12px 7px}.nav a{display:flex;gap:10px;align-items:center;text-decoration:none;color:#aeb6c6;border-radius:10px;padding:11px 12px;margin:3px 0}.nav a:hover,.nav a.active{background:#171c28;color:#fff}.nav a.active{box-shadow:inset 3px 0 var(--purple)}.main{min-width:0}.top{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 34px;background:rgba(8,10,15,.72);backdrop-filter:blur(12px);position:sticky;top:0;z-index:5}.top small{display:block;color:var(--muted);font-size:11px}.top strong{font-size:18px}.back{color:#aeb6c6;text-decoration:none;border:1px solid var(--line);padding:9px 12px;border-radius:9px}.page{max-width:1260px;margin:0 auto;padding:34px}.heading{display:flex;justify-content:space-between;gap:20px;align-items:flex-end;margin-bottom:28px}.eyebrow{font-size:10px;font-weight:900;letter-spacing:.16em;color:#826cff}.heading h1{font-size:30px;margin:7px 0 7px}.heading p{margin:0;color:var(--muted);max-width:720px;line-height:1.55}.grid{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:22px}.card{background:linear-gradient(180deg,rgba(18,23,33,.98),rgba(13,17,25,.98));border:1px solid var(--line);border-radius:16px;overflow:hidden}.cardhead{padding:20px 22px;border-bottom:1px solid var(--line)}.cardhead h2,.cardhead h3{margin:0 0 4px}.cardhead p{margin:0;color:var(--muted);font-size:12px}.section{padding:22px;border-bottom:1px solid var(--line)}.section:last-child{border-bottom:0}.sectiontitle{display:flex;align-items:center;gap:10px;margin-bottom:17px}.step{width:27px;height:27px;border-radius:8px;background:#211b44;color:#a58cff;display:grid;place-items:center;font-weight:900}.sectiontitle strong{font-size:15px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:15px}.wide{grid-column:1/-1}label span{display:block;color:#aeb6c6;font-size:11px;font-weight:700;margin:0 0 7px}input,select{width:100%;background:#0b0f16;border:1px solid #2a3242;color:#fff;border-radius:9px;padding:11px 12px;outline:0}input:focus,select:focus{border-color:#6f5cff;box-shadow:0 0 0 3px rgba(111,92,255,.13)}.toggleRow{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:12px 0;border-bottom:1px solid rgba(37,44,58,.65)}.toggleRow:last-child{border:0}.toggleRow b{display:block;font-size:13px}.toggleRow small{display:block;color:var(--muted);margin-top:3px;line-height:1.4}.switch{position:relative;width:46px;height:26px;flex:0 0 auto}.switch input{display:none}.switch i{position:absolute;inset:0;background:#252c38;border-radius:20px;cursor:pointer}.switch i:after{content:"";position:absolute;width:20px;height:20px;left:3px;top:3px;border-radius:50%;background:#8891a0;transition:.18s}.switch input:checked+i{background:#5748c8}.switch input:checked+i:after{left:23px;background:#fff}.hint{padding:12px 14px;border:1px solid #2b3350;background:#11172a;border-radius:10px;color:#aab4cb;line-height:1.5;font-size:12px;margin-top:14px}.warn{border-color:#4a3540;background:#1c1118;color:#d9a6b2}.actions{display:flex;justify-content:flex-end;gap:10px;padding:20px 22px}.btn{border:0;border-radius:9px;padding:11px 16px;font-weight:800;cursor:pointer}.primary{background:linear-gradient(135deg,#6653f4,#875fff);color:#fff}.secondary{background:#171d28;border:1px solid #303849;color:#dce1eb}.btn:disabled{opacity:.55;cursor:wait}.sidecard{padding:19px}.sidecard h3{margin:0 0 13px}.summary{display:grid;gap:10px}.summary div{display:flex;justify-content:space-between;gap:15px;padding-bottom:9px;border-bottom:1px solid var(--line)}.summary span{color:var(--muted)}.summary b{text-align:right}.ok{color:var(--green)}.existing{margin-top:22px}.nodeitem{padding:14px;border:1px solid var(--line);border-radius:11px;background:#0d1119;margin-top:10px}.nodeitemtop{display:flex;justify-content:space-between;gap:10px}.nodeitem strong{display:block}.nodeitem small{color:var(--muted)}.nodeitem button{margin-top:10px;width:100%}.modal{display:none;position:fixed;inset:0;z-index:50;background:rgba(0,0,0,.72);padding:22px;place-items:center}.modal.show{display:grid}.modalbox{width:min(760px,100%);background:#111620;border:1px solid #30384a;border-radius:16px;overflow:hidden}.modalhead{display:flex;justify-content:space-between;align-items:center;padding:18px 20px;border-bottom:1px solid var(--line)}.modalhead h2{margin:0}.close{background:none;border:0;color:#bbc3d1;font-size:28px;cursor:pointer}.modalbody{padding:20px}.secret{background:#080b10;border:1px solid #252d3c;border-radius:10px;padding:14px;white-space:pre-wrap;word-break:break-all;color:#d7dcef;min-height:80px;font:12px ui-monospace,SFMono-Regular,Menlo,monospace}.secretActions{display:flex;gap:10px;margin-top:12px}.notice{display:none;margin-top:14px;padding:12px;border-radius:9px}.notice.show{display:block}.error{background:#2a1119;border:1px solid #613144;color:#ffb2c1}.success{background:#10251f;border:1px solid #28584a;color:#a6f0d6}@media(max-width:900px){.shell{grid-template-columns:1fr}.side{display:none}.top{padding:0 18px}.page{padding:22px 16px}.grid{grid-template-columns:1fr}.heading{align-items:flex-start;flex-direction:column}.fields{grid-template-columns:1fr}.wide{grid-column:auto}.rightcol{order:-1}}
</style>
</head>
<body>
<div class="shell">
<aside class="side">
 <div class="brand"><div class="mark">N</div><div><b>NOD<span>EXA</span></b><small>ADMIN PANEL</small></div></div>
 <nav class="nav"><div class="navlabel">ADMINISTRATION</div><a href="/">Oversigt</a><a href="/#nodes">Nodes</a><a class="active" href="/admin/nodes/setup">Node Setup</a><a href="/admin/database-hosts">Database Hosts</a><a href="/admin/errors">Fejl</a><a href="/admin/update">Opdateringer</a></nav>
</aside>
<div class="main">
 <header class="top"><div><small>ADMINISTRATION · NODES</small><strong>Node Setup</strong></div><a class="back" href="/">← Til panelet</a></header>
 <main class="page">
  <div class="heading"><div><div class="eyebrow">NODEXA AGENT</div><h1>Opsæt en ny Node</h1><p>Konfigurér Node, HTTPS, firewall og Database Host direkte i Admin Panel. Når du gemmer, genererer Nodexa én installationskommando, som køres på den nye VPS.</p></div></div>
  <div class="grid">
   <form id="nodeForm" class="card">
    <div class="cardhead"><h2>Node konfiguration</h2><p>Alle værdier gemmes på Node-posten, så konfigurationen kan åbnes igen senere.</p></div>
    <section class="section"><div class="sectiontitle"><div class="step">1</div><strong>Grundlæggende</strong></div><div class="fields">
      <label><span>Node navn</span><input name="name" required placeholder="Gaming Node 01"></label>
      <label><span>Lokation</span><input name="location" value="Denmark" placeholder="Denmark"></label>
      <label class="wide"><span>Node FQDN</span><input name="fqdn" required placeholder="node.example.com"></label>
      <label><span>Forbindelse</span><select name="scheme"><option value="https" selected>HTTPS + Let's Encrypt</option><option value="http">HTTP</option></select></label>
      <label><span>Offentlig Agent port</span><input name="daemon_port" type="number" value="443" min="1" max="65535"></label>
      <label><span>SFTP port</span><input name="sftp_port" type="number" value="2022" min="1" max="65535"></label>
      <label><span>Let's Encrypt email</span><input name="ssl_email" type="email" placeholder="admin@example.com"></label>
    </div><div class="hint">Ved HTTPS bruger Nodexa port <b>443</b> offentligt og holder Agent internt på <b>127.0.0.1:8080</b> bag Nginx.</div></section>
    <section class="section"><div class="sectiontitle"><div class="step">2</div><strong>Kapacitet</strong></div><div class="fields"><label><span>RAM (MB)</span><input name="memory_mb" type="number" value="64000" min="128"></label><label><span>Disk (MB)</span><input name="disk_mb" type="number" value="500000" min="1024"></label></div></section>
    <section class="section"><div class="sectiontitle"><div class="step">3</div><strong>Firewall</strong></div><div class="toggleRow"><div><b>Konfigurér UFW automatisk</b><small>Åbner SSH, HTTPS/Agent og kun de valgte databaseporte.</small></div><label class="switch"><input name="configure_ufw" type="checkbox" checked><i></i></label></div></section>
    <section class="section"><div class="sectiontitle"><div class="step">4</div><strong>Database Host</strong></div>
      <div class="toggleRow"><div><b>Brug Node som Database Host</b><small>Installerer MariaDB og opretter automatisk Database Host i Nodexa.</small></div><label class="switch"><input id="dbEnabled" name="configure_database_host" type="checkbox"><i></i></label></div>
      <div id="dbOptions" style="display:none;margin-top:12px">
       <div class="toggleRow"><div><b>Tillad ekstern MariaDB</b><small>Påkrævet når Panel og Node er på forskellige VPS'er.</small></div><label class="switch"><input name="database_external" type="checkbox" checked><i></i></label></div>
       <div class="toggleRow"><div><b>Åbn port 3306 kun for Panel</b><small>Begrænser firewall-adgang til Panel-IP/hostname.</small></div><label class="switch"><input name="database_allow_3306" type="checkbox" checked><i></i></label></div>
       <div class="fields" style="margin-top:15px"><label class="wide"><span>Panel IP/hostname der må nå MariaDB</span><input name="database_panel_source" placeholder="panel.example.com"></label><label><span>Database admin-bruger</span><input name="database_username" value="nodexa_dbhost"></label><label><span>Database admin-password</span><input name="database_password" type="password" placeholder="Tom = generér sikkert password"></label></div>
       <div class="hint warn">Undgå at åbne port 3306 for hele internettet. Brug helst Panel-VPS'ens faste offentlige IP.</div>
      </div>
    </section>
    <div id="formError" class="notice error" style="margin:0 22px"></div>
    <div class="actions"><button type="button" class="btn secondary" onclick="location.href='/'">Annuller</button><button id="submitBtn" class="btn primary" type="submit">Opret Node & generér kommando</button></div>
   </form>
   <div class="rightcol">
    <div class="card sidecard"><h3>Installation</h3><div class="summary"><div><span>Panel</span><b id="summaryPanel">—</b></div><div><span>Node</span><b id="summaryFqdn">Ikke udfyldt</b></div><div><span>HTTPS</span><b id="summaryHttps" class="ok">Aktiv</b></div><div><span>Agent</span><b>8080 intern</b></div><div><span>Public</span><b id="summaryPort">443</b></div><div><span>Database Host</span><b id="summaryDb">Nej</b></div></div><div class="hint">Når Node er oprettet, kopierer du kun én kommando til Node-VPS'en. Resten af opsætningen kommer fra Admin Panel.</div></div>
    <div class="card sidecard existing"><h3>Eksisterende Nodes</h3><div id="nodes"><span style="color:var(--muted)">Indlæser…</span></div></div>
   </div>
  </div>
 </main>
</div>
</div>
<div id="configModal" class="modal"><div class="modalbox"><div class="modalhead"><div><div class="eyebrow">INSTALLATION</div><h2>Node kommando</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="modalbody"><p style="color:var(--muted)">Kør kommandoen som <b>root</b> på Node-serveren. Den indeholder Node-token og eventuelle Database Host credentials.</p><div id="installCommand" class="secret">••••••••••••••••••••••••••••••••</div><div class="secretActions"><button id="showSecret" class="btn secondary" onclick="toggleSecret()">Vis kommando</button><button class="btn primary" onclick="copyCommand()">Kopiér</button></div><div id="copyOk" class="notice success">Kommando kopieret.</div></div></div></div>
<script>
const TOKEN=localStorage.getItem('nodexa_panel_token');
const headers={Authorization:'Bearer '+TOKEN,Accept:'application/json','Content-Type':'application/json'};
let currentCommand='',secretVisible=false;
const form=document.getElementById('nodeForm');
const dbEnabled=document.getElementById('dbEnabled');
const dbOptions=document.getElementById('dbOptions');
function val(name){return form.elements[name]?.value ?? ''}
function checked(name){return !!form.elements[name]?.checked}
function refreshSummary(){document.getElementById('summaryFqdn').textContent=val('fqdn')||'Ikke udfyldt';const https=val('scheme')==='https';document.getElementById('summaryHttps').textContent=https?'Aktiv':'Deaktiveret';document.getElementById('summaryHttps').className=https?'ok':'';document.getElementById('summaryPort').textContent=https?'443':(val('daemon_port')||'8080');document.getElementById('summaryDb').textContent=checked('configure_database_host')?'Ja':'Nej';dbOptions.style.display=checked('configure_database_host')?'block':'none'}
form.addEventListener('input',refreshSummary);form.addEventListener('change',refreshSummary);
function showError(msg){const box=document.getElementById('formError');box.textContent=msg;box.classList.add('show')}
function clearError(){document.getElementById('formError').classList.remove('show')}
function openConfig(command){currentCommand=command||'';secretVisible=false;document.getElementById('installCommand').textContent='••••••••••••••••••••••••••••••••';document.getElementById('showSecret').textContent='Vis kommando';document.getElementById('copyOk').classList.remove('show');document.getElementById('configModal').classList.add('show')}
function closeModal(){document.getElementById('configModal').classList.remove('show');currentCommand='';secretVisible=false}
function toggleSecret(){secretVisible=!secretVisible;document.getElementById('installCommand').textContent=secretVisible?currentCommand:'••••••••••••••••••••••••••••••••';document.getElementById('showSecret').textContent=secretVisible?'Skjul kommando':'Vis kommando'}
async function copyCommand(){if(!currentCommand)return;await navigator.clipboard.writeText(currentCommand);document.getElementById('copyOk').classList.add('show')}
async function api(url,options={}){const r=await fetch(url,{...options,headers:{...headers,...(options.headers||{})}});const text=await r.text();let data={};try{data=text?JSON.parse(text):{}}catch{data={message:text||'Ukendt serverfejl'}}if(!r.ok)throw new Error(data.message||`HTTP ${r.status}`);return data}
async function loadNodes(){try{const d=await api('/api/nodes');const list=Array.isArray(d)?d:(Array.isArray(d.data)?d.data:[]);const wrap=document.getElementById('nodes');if(!list.length){wrap.innerHTML='<span style="color:var(--muted)">Ingen Nodes endnu.</span>';return}wrap.innerHTML=list.map(n=>`<div class="nodeitem"><div class="nodeitemtop"><div><strong>${escapeHtml(n.name)}</strong><small>${escapeHtml(n.fqdn)}:${n.daemon_port}</small></div><b>${escapeHtml(n.location||'—')}</b></div><button class="btn secondary" data-config="${n.id}">Vis installation</button></div>`).join('');wrap.querySelectorAll('[data-config]').forEach(b=>b.onclick=async()=>{try{const c=await api('/api/nodes/'+b.dataset.config+'/configuration');openConfig(c.install_command)}catch(e){alert(e.message)}})}catch(e){document.getElementById('nodes').innerHTML='<span style="color:#ff9aaf">'+escapeHtml(e.message)+'</span>'}}
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
form.addEventListener('submit',async e=>{e.preventDefault();clearError();const btn=document.getElementById('submitBtn');btn.disabled=true;btn.textContent='Opretter…';try{const https=val('scheme')==='https';const payload={name:val('name').trim(),location:val('location').trim()||null,fqdn:val('fqdn').trim(),scheme:val('scheme'),daemon_port:https?443:Number(val('daemon_port')||8080),sftp_port:Number(val('sftp_port')||2022),memory_mb:Number(val('memory_mb')),disk_mb:Number(val('disk_mb')),setup:{configure_ufw:checked('configure_ufw'),configure_database_host:checked('configure_database_host'),database_external:checked('database_external'),database_allow_3306:checked('database_allow_3306'),database_panel_source:val('database_panel_source').trim(),database_username:val('database_username').trim()||'nodexa_dbhost',database_password:val('database_password'),ssl_email:val('ssl_email').trim()}};const d=await api('/api/nodes',{method:'POST',body:JSON.stringify(payload)});openConfig(d.configuration?.install_command||'');await loadNodes()}catch(e){showError(e.message)}finally{btn.disabled=false;btn.textContent='Opret Node & generér kommando'}});
(async()=>{if(!TOKEN){location.href='/';return}try{const me=await api('/api/me');if(!me.is_admin){location.href='/';return}document.getElementById('summaryPanel').textContent=location.hostname;form.elements.database_panel_source.value=location.hostname;refreshSummary();await loadNodes()}catch{location.href='/'}})();
</script>
</body>
</html>
